using UnityEngine;

/// <summary>
/// 太空射击 - 玩家飞船
/// 挂载: PlayerShip
/// 组件: Rigidbody2D, BoxCollider2D, SpriteRenderer
/// </summary>
public class PlayerShip : MonoBehaviour
{
    [Header("移动")]
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private Vector2 boundaryMin = new Vector2(-8, -4);
    [SerializeField] private Vector2 boundaryMax = new Vector2(8, 4);

    [Header("射击")]
    [SerializeField] private Transform firePoint;
    [SerializeField] private GameObject bulletPrefab;
    [SerializeField] private float fireRate = 0.15f;

    [Header("状态")]
    [SerializeField] private int maxHealth = 3;

    private int currentHealth;
    private float nextFireTime;
    private bool isDead;

    public int Health => currentHealth;
    public event System.Action<int> OnHealthChanged;
    public event System.Action OnPlayerDied;

    private void Start()
    {
        currentHealth = maxHealth;
        OnHealthChanged?.Invoke(currentHealth);
    }

    private void Update()
    {
        if (isDead) return;

        // 移动
        float h = Input.GetAxisRaw("Horizontal");
        float v = Input.GetAxisRaw("Vertical");
        Vector2 move = new Vector2(h, v).normalized;
        Vector2 newPos = (Vector2)transform.position + move * moveSpeed * Time.deltaTime;
        newPos.x = Mathf.Clamp(newPos.x, boundaryMin.x, boundaryMax.x);
        newPos.y = Mathf.Clamp(newPos.y, boundaryMin.y, boundaryMax.y);
        transform.position = newPos;

        // 射击
        if (Input.GetButton("Fire1") && Time.time >= nextFireTime)
        {
            Shoot();
            nextFireTime = Time.time + fireRate;
        }
    }

    private void Shoot()
    {
        if (bulletPrefab == null || firePoint == null) return;
        Instantiate(bulletPrefab, firePoint.position, Quaternion.identity);
    }

    public void TakeDamage(int damage)
    {
        if (isDead) return;
        currentHealth -= damage;
        OnHealthChanged?.Invoke(currentHealth);
        if (currentHealth <= 0)
            Die();
    }

    private void Die()
    {
        isDead = true;
        OnPlayerDied?.Invoke();
        gameObject.SetActive(false);
    }

    public void Revive()
    {
        isDead = false;
        currentHealth = maxHealth;
        gameObject.SetActive(true);
        OnHealthChanged?.Invoke(currentHealth);
    }
}

