using UnityEngine;

/// <summary>
/// 敌人生成器
/// 挂载: EnemySpawner
/// </summary>
public class EnemySpawner : MonoBehaviour
{
    [Header("生成设置")]
    [SerializeField] private GameObject[] enemyPrefabs;
    [SerializeField] private float spawnInterval = 1.5f;
    [SerializeField] private float spawnXRange = 7f;
    [SerializeField] private float spawnY = 6f;

    [Header("难度递增")]
    [SerializeField] private float minInterval = 0.5f;
    [SerializeField] private float intervalDecrease = 0.05f;

    private float currentInterval;
    private float spawnTimer;
    private bool isSpawning = true;

    private void Start()
    {
        currentInterval = spawnInterval;
    }

    private void Update()
    {
        if (!isSpawning) return;

        spawnTimer += Time.deltaTime;
        if (spawnTimer >= currentInterval)
        {
            SpawnEnemy();
            spawnTimer = 0f;
            // 难度递增
            currentInterval = Mathf.Max(minInterval, currentInterval - intervalDecrease);
        }
    }

    private void SpawnEnemy()
    {
        if (enemyPrefabs.Length == 0) return;
        int idx = Random.Range(0, enemyPrefabs.Length);
        float x = Random.Range(-spawnXRange, spawnXRange);
        Vector3 pos = new Vector3(x, spawnY, 0);
        Instantiate(enemyPrefabs[idx], pos, Quaternion.identity);
    }

    public void StartSpawning() { isSpawning = true; }
    public void StopSpawning() { isSpawning = false; }
}

