using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 太空射击HUD
/// 挂载: Canvas
/// </summary>
public class GameHUD : MonoBehaviour
{
    [SerializeField] private Text scoreText;
    [SerializeField] private Text healthText;
    [SerializeField] private GameObject gameOverPanel;

    private void Start()
    {
        GameManager gm = GameManager.Instance;
        if (gm != null)
        {
            gm.OnScoreChanged += s => { if (scoreText) scoreText.text = $"Score: {s}"; };
            gm.OnGameStateChanged += state => { if (gameOverPanel) gameOverPanel.SetActive(state == GameManager.GameState.GameOver); };
        }

        PlayerShip player = FindObjectOfType<PlayerShip>();
        if (player != null)
            player.OnHealthChanged += h => { if (healthText) healthText.text = $"HP: {h}"; };

        if (gameOverPanel) gameOverPanel.SetActive(false);
    }

    public void OnRestartButton()
    {
        GameManager.Instance?.Restart();
    }
}
